contracts/core_justice/EnhancedOraculumC.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.29;

// © Copyright Marcello Stanca - Italy - Florence. Author and owner of the Solidary.it ecosystem and this smart contract. The ecosystem and its logical components (.sol files and scripts) are protected by copyright.


/**
 * @title SolidarySystemOraculumCaritatis
 * @notice Sistema avanzato di verifica identità per aiuti umanitari:
 *         - registrazione enti verificatori (Caritas, ONG)
 *         - attestazione “BlessedSoul” con prove su IPFS (no dati sensibili on-chain)
 *         - statistiche per regione/contesto (guerre, disastri naturali)
 *         - integrazione (hook) con ReputationManager e Hub
 *         - emergenza: pausa e sospensione verificatori
 *
 * Sicurezza:
 *  - UUPS Upgradeable
 *  - AccessControl (DEFAULT_ADMIN_ROLE, VERIFICATOR_ROLE, AUDITOR_ROLE)
 *  - Pausable (emergenza)
 *  - NESSUN segreto on-chain: solo CID/pointer
 */

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/StringsUpgradeable.sol";

contract SolidarySystemOraculumCaritatis is
    Initializable,
    AccessControlUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    using StringsUpgradeable for uint256;
    using StringsUpgradeable for address;

    // ───────────────────────── Roles ─────────────────────────
    bytes32 public constant VERIFICATOR_ROLE = keccak256("VERIFICATOR_ROLE");
    bytes32 public constant AUDITOR_ROLE     = keccak256("AUDITOR_ROLE");

    // ───────────────────────── Data ─────────────────────────
    struct BlessedSoul {
        bool    isPrivileged;
        uint256 blessingTimestamp;
        address verifiedBy;
        string  regionCode;        // es. "UA-12"
        string  crisisType;        // "war","earthquake","famine",...
        uint256 privilegeLevel;    // 1..10
        string  verificationCID;   // Prove su IPFS (no dati personali)
        uint256 lastVerification;
    }

    struct Verificator {
        string  organizationName;  // es. "Caritas Internationalis"
        string  regionAuthority;   // es. "Europe-Emergency"
        uint256 verificationCount;
        bool    isActive;
        string  credentialsCID;    // credenziali/verifiche su IPFS
    }

    mapping(address => BlessedSoul) public blessedSouls;        // wallet → stato
    mapping(address => Verificator) public verificators;        // verificatore → profilo
    mapping(string => address[]) public regionBlessedSouls;     // regione → elenco wallet

    // Riferimenti ecosistema
    address public solidaryHub;              // SolidarySystemSolidarySystem
    address public impactLogger;             // opzionale
    address public reputationManager;        // SolidarySystemReputationManager (opzionale)

    // Statistiche
    uint256 public totalBlessedSouls;
    uint256 public totalVerifications;

    // Storage pointers (NO secrets reali)
    string public ipfsBaseURI;

    // Eventi
    event SoulBlessed(address indexed soul, address indexed verificator, string region, string crisisType, string verificationCID);
    event BlessingUpdated(address indexed soul, uint256 newPrivilegeLevel);
    event BlessingRevoked(address indexed soul, address indexed by, string reason);
    event VerificatorRegistered(address indexed verificator, string organization);
    event VerificatorStatusChanged(address indexed verificator, bool isActive);
    event CrossChainVerification(address indexed soul, uint256 chainId, bool verified);
    event StorageConfigured(string ipfsBaseURI);
    event IntegrationLinked(address hub, address impactLogger, address reputationManager);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    // ───────────────────── Initialization ───────────────────
    function initialize(
        address admin,
        address _solidaryHub,
        address _impactLogger,
        address _reputationManager
    ) public initializer {
        __AccessControl_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(VERIFICATOR_ROLE, admin); // l’admin è il primo verificatore “bootstrap”
        _grantRole(AUDITOR_ROLE, admin);

        solidaryHub       = _solidaryHub;
        impactLogger      = _impactLogger;
        reputationManager = _reputationManager;

        emit IntegrationLinked(_solidaryHub, _impactLogger, _reputationManager);
    }

    // ───────────────────── Verificatori ─────────────────────
    function registerVerificator(
        address verificator,
        string memory organizationName,
        string memory regionAuthority,
        string memory credentialsData
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(verificator != address(0), "invalid verificator");

        string memory credentialsCID = _uploadToIPFS(bytes(credentialsData));
        verificators[verificator] = Verificator({
            organizationName: organizationName,
            regionAuthority: regionAuthority,
            verificationCount: 0,
            isActive: true,
            credentialsCID: credentialsCID
        });

        _grantRole(VERIFICATOR_ROLE, verificator);
        emit VerificatorRegistered(verificator, organizationName);
        emit VerificatorStatusChanged(verificator, true);
    }

    function setVerificatorActive(address verificator, bool active)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        require(bytes(verificators[verificator].organizationName).length != 0, "not registered");
        verificators[verificator].isActive = active;
        if (!active && hasRole(VERIFICATOR_ROLE, verificator)) {
            // lasciamo il ruolo ma il flag attivo = false blocca le azioni
        }
        emit VerificatorStatusChanged(verificator, active);
    }

    // ───────────────────── Blessings ────────────────────────
    function blessSoul(
        address soul,
        string memory regionCode,
        string memory crisisType,
        uint256 privilegeLevel,
        string memory verificationData
    ) external whenNotPaused onlyRole(VERIFICATOR_ROLE) returns (string memory verificationCID) {
        require(soul != address(0), "invalid soul");
        require(privilegeLevel >= 1 && privilegeLevel <= 10, "privilege 1..10");
        require(verificators[msg.sender].isActive, "verificator inactive");

        verificationCID = _storeVerificationProof(verificationData);

        blessedSouls[soul] = BlessedSoul({
            isPrivileged: true,
            blessingTimestamp: block.timestamp,
            verifiedBy: msg.sender,
            regionCode: regionCode,
            crisisType: crisisType,
            privilegeLevel: privilegeLevel,
            verificationCID: verificationCID,
            lastVerification: block.timestamp
        });

        regionBlessedSouls[regionCode].push(soul);
        totalBlessedSouls++;
        verificators[msg.sender].verificationCount++;

        _logHumanitarianImpact(soul, regionCode, crisisType, privilegeLevel);
        _notifyReputationPositive(soul, privilegeLevel); // opzionale: +reputazione

        emit SoulBlessed(soul, msg.sender, regionCode, crisisType, verificationCID);
    }

    function updateBlessing(
        address soul,
        uint256 newPrivilegeLevel,
        string memory newVerificationData
    ) external whenNotPaused onlyRole(VERIFICATOR_ROLE) returns (string memory newCID) {
        require(blessedSouls[soul].isPrivileged, "no blessing");
        require(verificators[msg.sender].isActive, "verificator inactive");
        require(newPrivilegeLevel >= 1 && newPrivilegeLevel <= 10, "privilege 1..10");

        newCID = _storeVerificationProof(newVerificationData);
        blessedSouls[soul].privilegeLevel   = newPrivilegeLevel;
        blessedSouls[soul].verificationCID  = newCID;
        blessedSouls[soul].lastVerification = block.timestamp;
        totalVerifications++;

        _notifyReputationPositive(soul, (newPrivilegeLevel >= 7 ? 2 : 1));
        emit BlessingUpdated(soul, newPrivilegeLevel);
    }

    function revokeBlessing(address soul, string calldata reason)
        external
        onlyRole(AUDITOR_ROLE)
    {
        require(blessedSouls[soul].isPrivileged, "not blessed");
        blessedSouls[soul].isPrivileged = false;
        blessedSouls[soul].lastVerification = block.timestamp;
        _notifyReputationNegative(soul, 5); // penalità moderata
        emit BlessingRevoked(soul, msg.sender, reason);
    }

    // ───────────────────── Cross-chain log ──────────────────
    function verifySoulAcrossChains(
        address soul,
        uint256 chainId,
        bool isVerified
    ) external onlyRole(VERIFICATOR_ROLE) {
        require(verificators[msg.sender].isActive, "verificator inactive");
        blessedSouls[soul].lastVerification = block.timestamp;
        totalVerifications++;
        emit CrossChainVerification(soul, chainId, isVerified);
    }

    // ───────────────────── Views ────────────────────────────
    function getRegionStatistics(string memory regionCode)
        external
        view
        returns (uint256 totalSouls, uint256 averagePrivilegeLevel, string memory commonCrisisType)
    {
        address[] memory souls = regionBlessedSouls[regionCode];
        uint256 totalPrivilege = 0;
        uint256 activeCount = 0;
        for (uint256 i = 0; i < souls.length; i++) {
            BlessedSoul memory s = blessedSouls[souls[i]];
            if (s.isPrivileged) {
                totalPrivilege += s.privilegeLevel;
                activeCount++;
            }
        }
        totalSouls = souls.length;
        averagePrivilegeLevel = activeCount > 0 ? totalPrivilege / activeCount : 0;
        commonCrisisType = souls.length > 0 ? blessedSouls[souls[0]].crisisType : "none";
    }

    // ───────────────────── Integration & storage ────────────
    function linkIntegration(address _hub, address _impactLogger, address _reputationManager)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        solidaryHub       = _hub;
        impactLogger      = _impactLogger;
        reputationManager = _reputationManager;
        emit IntegrationLinked(_hub, _impactLogger, _reputationManager);
    }

    function configureStorage(string calldata _ipfsBaseURI)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        ipfsBaseURI = _ipfsBaseURI; // solo pointer; niente chiavi on-chain
        emit StorageConfigured(_ipfsBaseURI);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) { _unpause(); }

    // ───────────────────── Internal helpers ────────────────
    function _storeVerificationProof(string memory verificationData) internal view returns (string memory) {
        // salvare SOLO un CID/IPFS-friendly JSON con prove off-chain
        bytes memory proofData = abi.encodePacked(
            '{"verifier":"', _addrToString(msg.sender),
            '","timestamp":', block.timestamp.toString(),
            ',"data":"', verificationData, '"}'
        );
        return _uploadToIPFS(proofData);
    }

    function _logHumanitarianImpact(
        address soul,
        string memory regionCode,
        string memory crisisType,
        uint256 privilegeLevel
    ) internal {
        if (impactLogger != address(0)) {
            // placeholder: in produzione, chiama il logger con ABI concreta
            // bytes memory payload = abi.encodeWithSignature(
            //   "logImpact(string,string,string,uint256,uint256,string,uint256,string)",
            //   "humanitarian","identity_verification",
            //   string(abi.encodePacked("Verified soul in ", regionCode)),
            //   1, 0, regionCode, 1, "humanitarian_verification"
            // );
            // (bool ok,) = impactLogger.call(payload);
            // ok; // ignore
            soul; regionCode; crisisType; privilegeLevel;
        }
    }

    function _notifyReputationPositive(address subject, uint256 magnitude) internal {
        if (reputationManager != address(0)) {
            // bytes memory payload = abi.encodeWithSignature(
            //   "attest(address,int256,uint256,string,string)",
            //   subject, int256(10 * magnitude), 10, "identity", "" // delta, weight
            // );
            // (bool ok,) = reputationManager.call(payload);
            // ok;
            subject; magnitude;
        }
    }

    function _notifyReputationNegative(address subject, uint256 magnitude) internal {
        if (reputationManager != address(0)) {
            // bytes memory payload = abi.encodeWithSignature(
            //   "attest(address,int256,uint256,string,string)",
            //   subject, -int256(10 * magnitude), 10, "identity", ""
            // );
            // (bool ok,) = reputationManager.call(payload);
            // ok;
            subject; magnitude;
        }
    }

    function _uploadToIPFS(bytes memory data) internal view returns (string memory cid) {
        // simulazione: genera un “CID” deterministic-like (NO upload reale on-chain)
        bytes32 hash = keccak256(abi.encodePacked(data, block.timestamp, totalBlessedSouls));
        cid = string(abi.encodePacked("simulated:ipfs:", _bytes32ToHex(hash)));
        return cid;
    }

    // ───────────────────── Utils ───────────────────────────
    function _bytes32ToHex(bytes32 v) internal pure returns (string memory) {
        bytes memory s = new bytes(64);
        for (uint256 i = 0; i < 32; i++) {
            bytes1 b = v[i];
            bytes1 hi = bytes1(uint8(b) / 16);
            bytes1 lo = bytes1(uint8(b) % 16);
            s[2*i]   = _nibble(hi);
            s[2*i+1] = _nibble(lo);
        }
        return string(s);
    }
    function _nibble(bytes1 b) internal pure returns (bytes1 c) {
        uint8 v = uint8(b);
        return v < 10 ? bytes1(v + 0x30) : bytes1(v + 0x57);
    }
    function _addrToString(address a) internal pure returns (string memory) {
        return StringsUpgradeable.toHexString(uint256(uint160(a)), 20);
    }

    // ───────────────────── UUPS auth ───────────────────────
    function _authorizeUpgrade(address newImplementation) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/core/SolidarySystemHub.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.29;

// © Copyright Marcello Stanca - Italy - Florence. Author and owner of the Solidary.it ecosystem and this smart contract. The ecosystem and its logical components (.sol files and scripts) are protected by copyright.


/**
 * @title SolidarySystem (Rector Orbis - The Ruler of the World)
 * @author
 * © 2025 Marcello Stanca - Lawyer, Firenze, Italy. All Rights Reserved.
 * @notice Core Hub del "Solidary System": registra/coordina moduli, storage pointers (no secrets on-chain),
 *          orchestrazioni cross-modulo, stato/health dell’ecosistema, emergency mode.
 *
 * Sicurezza/Design:
 * - UUPS + AccessControl + Pausable + ReentrancyGuard
 */

// File: contracts/core/SolidarySystem.sol

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "../libraries/SolidaryIpfsUtils.sol";
import "../libraries/SolidaryModuleUtils.sol"; // External library: link at deploy
import "../libraries/SolidaryHubLogic.sol";
import "../libraries/SolidaryHubUtils.sol";
import "../libraries/SolidaryTokenRouter.sol"; // External library: link at deploy

contract SolidarySystemHub is
    Initializable,
    AccessControlUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    // ───────────────────────────────── Roles & Layers ─────────────────────────────
    bytes32 public constant ECOSYSTEM_ADMIN  = keccak256("ECOSYSTEM_ADMIN");
    bytes32 public constant MODULE_MANAGER   = keccak256("MODULE_MANAGER");
    bytes32 public constant ORACLE_ROLE      = keccak256("ORACLE_ROLE");
    bytes32 public constant EMERGENCY_ROLE   = keccak256("EMERGENCY_ROLE");
    bytes32 public constant STORAGE_MANAGER  = keccak256("STORAGE_MANAGER");

    uint8 public constant LAYER_CORE         = 1;
    uint8 public constant LAYER_PLANETARY    = 2;
    uint8 public constant LAYER_SATELLITES   = 3;
    uint8 public constant LAYER_INFRASTRUCTURE= 4;
    uint8 public constant LAYER_BRIDGES      = 5;
    uint8 public constant LAYER_ANALYTICS    = 6;
    uint8 public constant LAYER_GOVERNANCE   = 7;

    // ───────────────────────────────── Data structures ────────────────────────────

    struct EnhancedModuleInfo {
        address contractAddress;
        string moduleName;
        uint8 layer;
        bool active;
        uint256 version;
        string moduleType;
        string ipfsCID;
        uint256 lastInteraction;
        uint256 successRate;
        uint256 totalInteractions;
        address[] dependencies;
        address[] dependents;
    }
    struct EcosystemHealth {
        uint256 overallScore;
        uint256 moduleHealth;
        uint256 crossChainHealth;
        uint256 reputationHealth;
        uint256 impactHealth;
        uint256 storageHealth;
        string healthCID;
        uint256 lastCheck;
    }
    struct StorageConfiguration {
        string nftStorageAPIKey;
        string pinataJWT;
        string ipfsBaseURI;
        bool storageEnabled;
        uint256 totalCIDsStored;
        string storageAnalyticsCID;
    }
    struct EnhancedEcosystemState {
        uint256 totalUsers;
        uint256 totalImpact;
        uint256 globalReputation;
        uint256 totalTransactions;
        uint256 crossChainVolume;
        uint256 carbonFootprint;
        uint256 totalValueLocked;
        bool emergencyMode;
        string stateCID;
    }

    // ───────────────────────────────── State ──────────────────────────────────────
    mapping(uint8 => address[]) public modulesByLayer;
    mapping(address => EnhancedModuleInfo) public modules;
    mapping(string => address) public moduleByName;
    mapping(string => address[]) public modulesByType;

    // Core references 
    address public solidaryOrchestrator; address public oceanMangaNFT; address public lunaComicsFT; address public solidaryMetrics; address public reputationManager; address public impactLogger; address public moduleRouter; address public multiChainOrchestrator;

    StorageConfiguration public storageConfig;
    EcosystemHealth public ecosystemHealth;
    EnhancedEcosystemState public ecosystemState;

    // Stats
    uint256 public totalModuleRegistrations; uint256 public totalCrossModuleCalls; uint256 public totalEmergencyEvents; uint256 public totalRouteCalls;

    // ───────────────────────────────── Events ─────────────────────────────────────
    event ModuleRegistered(address indexed moduleAddress, string moduleName, uint8 layer, string moduleType);
    event ModuleActivated(address indexed moduleAddress, bool status);
    event EcosystemStateUpdated(uint256 totalUsers, uint256 totalImpact, uint256 globalReputation, string stateCID);
    event EmergencyTriggered(address indexed trigger, string reason);
    event CrossModuleCallExecuted(address indexed from, address indexed to, bool success, bytes result);
    event StorageConfigured(bool storageEnabled, string ipfsBaseURI, address configuredBy);
    event EcosystemHealthUpdated(uint256 overallScore, string healthCID);
    event ModuleDependencyAdded(address indexed module, address indexed dependency);
    event EcosystemInitialized(address orchestrator, address nftPlanet, address ftSatellite);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(address initialAdmin) public initializer {
        __AccessControl_init();
        __Pausable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(ECOSYSTEM_ADMIN,  initialAdmin);
        _grantRole(MODULE_MANAGER,   initialAdmin);
        _grantRole(ORACLE_ROLE,      initialAdmin);
        _grantRole(EMERGENCY_ROLE,   initialAdmin);
        _grantRole(STORAGE_MANAGER,  initialAdmin);

        // ✅ UTILIZZA LA LIBRERIA PER L'INIZIALIZZAZIONE DELLO STATO (PIÙ LEGGERO)
        (
            ecosystemState.totalUsers, ecosystemState.totalImpact, ecosystemState.globalReputation, 
            ecosystemState.totalTransactions, ecosystemState.crossChainVolume, ecosystemState.carbonFootprint, 
            ecosystemState.totalValueLocked, ecosystemState.emergencyMode, ecosystemState.stateCID
        ) = abi.decode(
            SolidaryModuleUtils.setInitialEcosystemStateLogic(),
            (uint256, uint256, uint256, uint256, uint256, uint256, uint256, bool, string)
        ); // Funzione della libreria esterna, linkata

        // ✅ ASSEGNAZIONE DIRETTA DEI DUE STRUCT PICCOLI 
        ecosystemHealth = EcosystemHealth({
             overallScore: 100, moduleHealth: 100, crossChainHealth: 100, reputationHealth: 100, 
             impactHealth: 100, storageHealth: 100, healthCID: "", lastCheck: block.timestamp
        });
        storageConfig = StorageConfiguration({
             nftStorageAPIKey: "", pinataJWT: "", ipfsBaseURI: "", 
             storageEnabled: false, totalCIDsStored: 0, storageAnalyticsCID: ""
        });
    }

    // ───────────────────────────── Ecosystem bootstrap ────────────────────────────
    function initializeEcosystem(
        address _orchestrator, address _nftPlanet, address _ftSatellite, 
        address _metrics, address _reputationManager, address _impactLogger, 
        address _moduleRouter, address _multiChainOrchestrator
    ) external onlyRole(ECOSYSTEM_ADMIN) {
        solidaryOrchestrator = _orchestrator; oceanMangaNFT = _nftPlanet; lunaComicsFT = _ftSatellite; 
        solidaryMetrics = _metrics; reputationManager = _reputationManager; impactLogger = _impactLogger; 
        moduleRouter = _moduleRouter; multiChainOrchestrator = _multiChainOrchestrator;

        _registerCoreModule(_orchestrator, "SolidaryOrchestrator", LAYER_CORE, "orchestrator");
        _registerCoreModule(_nftPlanet, "OceanMangaNFT", LAYER_PLANETARY, "nft");
        _registerCoreModule(_ftSatellite, "LunaComicsFT", LAYER_SATELLITES, "ft");
        _registerCoreModule(_metrics, "SolidaryMetrics", LAYER_ANALYTICS, "metrics");
        _registerCoreModule(_reputationManager, "ReputationManager", LAYER_INFRASTRUCTURE, "reputation");
        _registerCoreModule(_impactLogger, "ImpactLogger", LAYER_INFRASTRUCTURE, "impact");
        _registerCoreModule(_moduleRouter, "ModuleRouter", LAYER_INFRASTRUCTURE, "router");
        _registerCoreModule(_multiChainOrchestrator,"UniversalMultiChainOrchestratorV2", LAYER_BRIDGES, "bridge");

        emit EcosystemInitialized(_orchestrator, _nftPlanet, _ftSatellite);
    }

    // ───────────────────────────── Module management ──────────────────────────────
    function _registerCoreModule(
        address moduleAddress, string memory moduleName, uint8 layer, string memory moduleType
    ) internal {
        if (moduleAddress == address(0)) return;

        modules[moduleAddress] = EnhancedModuleInfo({
            contractAddress: moduleAddress,
            moduleName: moduleName,
            layer: layer,
            active: true,
            version: 1,
            moduleType: moduleType,
            ipfsCID: "",
            lastInteraction: block.timestamp,
            successRate: 100,
            totalInteractions: 0,
            dependencies: new address[](0),
            dependents: new address[](0)
        });

        modulesByLayer[layer].push(moduleAddress);
        moduleByName[moduleName] = moduleAddress;
        modulesByType[moduleType].push(moduleAddress);

        totalModuleRegistrations++;
        emit ModuleRegistered(moduleAddress, moduleName, layer, moduleType);
    }

    function registerEnhancedModule(
        address contractAddress, string memory moduleName, uint8 layer, string memory moduleType,
        address[] memory dependencies, string memory metadata
    ) external onlyRole(MODULE_MANAGER) returns (string memory moduleCID) {
        require(contractAddress != address(0), "Invalid contract");
        require(layer >= 1 && layer <= 7, "Invalid layer");
        require(modules[contractAddress].contractAddress == address(0), "Already registered");

        moduleCID = _uploadToIPFS(bytes(metadata));

        modules[contractAddress] = EnhancedModuleInfo({
            contractAddress: contractAddress,
            moduleName: moduleName,
            layer: layer,
            active: true,
            version: 1,
            moduleType: moduleType,
            ipfsCID: moduleCID,
            lastInteraction: block.timestamp,
            successRate: 100,
            totalInteractions: 0,
            dependencies: dependencies,
            dependents: new address[](0)
        });

        for (uint256 i = 0; i < dependencies.length; i++) {
            modules[dependencies[i]].dependents.push(contractAddress);
            SolidarySystemHubLogic.addDependent(modules[dependencies[i]].dependents, contractAddress);
            emit ModuleDependencyAdded(contractAddress, dependencies[i]);
        }

        modulesByLayer[layer].push(contractAddress);
        moduleByName[moduleName] = contractAddress;
        modulesByType[moduleType].push(contractAddress);

        totalModuleRegistrations++;
        emit ModuleRegistered(contractAddress, moduleName, layer, moduleType);
    }

    function setModuleStatus(address moduleAddress, bool active) external onlyRole(MODULE_MANAGER) {
        require(modules[moduleAddress].contractAddress != address(0), "Module not registered");
        modules[moduleAddress].active = active;
        emit ModuleActivated(moduleAddress, active);
    }

    // ───────────────────────────── Cross-module orchestration ─────────────────────
    function crossModuleCall(address targetModule, bytes calldata data)
        public nonReentrant returns (bytes memory)
    {
        require(modules[targetModule].active, "Target inactive");
        require(
            hasRole(MODULE_MANAGER, msg.sender) || hasRole(ECOSYSTEM_ADMIN, msg.sender) || _isModule(msg.sender),
            "Unauthorized cross-call"
        );

        modules[targetModule].lastInteraction = block.timestamp;
        modules[targetModule].totalInteractions++;

        (bool success, bytes memory result) = targetModule.call(data);

        if (success) {
            modules[targetModule].successRate = (modules[targetModule].successRate * 99 + 100) / 100;
        } else {
            modules[targetModule].successRate = (modules[targetModule].successRate * 99) / 100;
        }

        totalCrossModuleCalls++;
        emit CrossModuleCallExecuted(msg.sender, targetModule, success, result);
        require(success, "Cross-module call failed");
        return result;
    }

    function orchestrateMultiModuleCall(address[] memory targetModules, bytes[] memory data)
        external onlyRole(ECOSYSTEM_ADMIN) returns (bool[] memory successes, bytes[] memory results)
    {
        require(targetModules.length == data.length, "Length mismatch");
        successes = new bool[](targetModules.length);
        results   = new bytes[](targetModules.length);

        for (uint256 i = 0; i < targetModules.length; i++) {
            if (modules[targetModules[i]].active) {
                // chiamata interna (no `this.`), preserva msg.sender = ECOSYSTEM_ADMIN
                try this.crossModuleCall(targetModules[i], data[i]) returns (bytes memory res) {
                    successes[i] = true;
                    results[i] = res;
                } catch (bytes memory err) {
                    successes[i] = false;
                    results[i] = err;
                }
            } else {
                successes[i] = false;
                results[i] = abi.encode("Module inactive");
            }
        }
    }

    // ───────────────────────────── IPFS utils (sim) ───────────────────────────────

    /**
     * @dev Funzione interna RISCRITTA per fungere da wrapper leggero.
     * @notice Chiama la logica complessa di generazione CID (IPFS) che è stata spostata in SolidaryIpfsUtils.
     * @param data Dati da caricare su IPFS simulato.
     */
    function _uploadToIPFS(bytes memory data) internal view returns (string memory cid) {
    // La logica costosa è ora nella libreria. Qui c'è solo la chiamata.
        return SolidaryIpfsUtils.generateSimulatedCID(
            data,
            block.timestamp,
            totalRouteCalls // Variabile di stato del Hub utilizzata per l'entropia della simulazione
        );
    }

    // ───────────────────────────── View helpers ───────────────────────────────────

    function _isModule(address account) internal pure returns (bool) {
        return SolidarySystemHubLogic.isValidModule(account);
    }

    function getEnhancedModuleInfo(address moduleAddress) external view returns (EnhancedModuleInfo memory) {
        return modules[moduleAddress];
    }
    function getModulesByLayer(uint8 layer) external view returns (address[] memory) {
        return modulesByLayer[layer];
    }
    function getModuleByName(string memory moduleName) external view returns (address) {
        return moduleByName[moduleName];
    }
    function getModulesByType(string memory moduleType) external view returns (address[] memory) {
        return modulesByType[moduleType];
    }
    function getEnhancedEcosystemState() external view returns (EnhancedEcosystemState memory) {
        return ecosystemState;
    }
    function getEcosystemHealth() external view returns (EcosystemHealth memory) {
        return ecosystemHealth;
    }
    function getStorageConfiguration() external view returns (StorageConfiguration memory) {
        return storageConfig;
    }
    function isEmergencyMode() external view returns (bool) {
        return ecosystemState.emergencyMode || paused();
    }
    function calculateEcosystemHealthScore() external view returns (uint256) {
        return SolidaryHubUtils.calculateEcosystemHealthScore(
            ecosystemState.totalUsers,
            ecosystemState.totalImpact,
            ecosystemState.globalReputation
        );
    }

    // ⚠️ WRAPPER LEGGERO CHE SOSTITUISCE LA LOGICA COSTOSA ORIGINALE
    /**
     * @notice Sostituisce la vecchia logica di _countActiveModules (ciclo for) con una chiamata alla Libreria.
     * @dev Manteniamo il nome _countActiveModules per coerenza con le vecchie chiamate (es. getEcosystemStatistics).
     */
    function _countActiveModules() internal view returns (uint256) {
        // La logica complessa di calcolo (es. ciclo for) è stata spostata.
        return SolidaryModuleUtils.countActiveModulesLogic(
            totalModuleRegistrations,
            0
        ); // Funzione della libreria esterna, linkata
    }

    function getEcosystemStatistics() external view returns (
        uint256 totalModules, uint256 activeModules, uint256 totalCalls, uint256 totalEmergencies, uint256 totalCIDs
    ) {
        return (
            totalModuleRegistrations,
            _countActiveModules(), // ✅ CHIAMATA ALLA FUNZIONE LEGGERA
            totalCrossModuleCalls,
            totalEmergencyEvents,
            storageConfig.totalCIDsStored
        );
    }

    // ───────────────────────────── UUPS auth ──────────────────────────────────────
    function _authorizeUpgrade(address newImplementation) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}

    // ───────────────────────────── Emergency Mode (SOLO API VUOTE) ──────────────────────────
    // NOTA: Le funzioni di emergenza complesse (triggerEmergency, _enableCriticalModules) 
    // sono state eliminate per risparmiare bytecode.

    // API vuote o placeholder per mantenere l'interfaccia (se strettamente necessarie)
    function triggerEmergency(string memory reason) external onlyRole(EMERGENCY_ROLE) {
        // La logica complessa è stata eliminata. Qui si imposta solo lo stato.
        ecosystemState.emergencyMode = true;
        totalEmergencyEvents++;
        emit EmergencyTriggered(msg.sender, reason);
        _pause();
    }

    function resolveEmergency(string memory /*resolutionNote*/) external onlyRole(EMERGENCY_ROLE) {
        // La logica complessa è stata eliminata. Qui si resetta solo lo stato.
        ecosystemState.emergencyMode = false;
        _unpause();
        // Aggiungi qui l'emit ResolutionEvent se lo definisci
    }

    // Funzione placeholder per la logica di salute costosa (DA COMPLETARE IN LIBRERIA)
    function _calculateEcosystemHealth() internal {
        // Sostituisci questo con una chiamata a una funzione LIBRARY.
        // Ad esempio: (uint256 score, string memory cid) = SolidaryHealthUtils.calculateHealthLogic();
        // Per ora, solo un placeholder leggero.
        ecosystemHealth.overallScore = 100;
        ecosystemHealth.lastCheck = block.timestamp;
        emit EcosystemHealthUpdated(ecosystemHealth.overallScore, ecosystemHealth.healthCID);
    }

    function calculateEcosystemHealthScore(
        uint256 totalUsers,
        uint256 totalImpact,
        uint256 globalReputation
    ) internal pure returns (uint256) {
        // Esempio di calcolo
        return totalUsers + totalImpact + globalReputation;
    }
}

contracts/interoperability_bridges/Unive.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.29;

// © Copyright Marcello Stanca - Italy - Florence. Author and owner of the Solidary.it ecosystem and this smart contract. The ecosystem and its logical components (.sol files and scripts) are protected by copyright.


/**
 * UniversalMultiChainOrchestratorV2
 *
 * - Orchestratore multi-chain per l'ecosistema Solidary
 * - Collega OceanMangaNFT (ERC1155), LunaComicsFT (ERC20), SolidaryMetrics
 * - Espone API attese da SolidaryMetrics: nftPlanetContract, ftSatelliteContract,
 *   totalQuantumLinks, totalStellarValue, getStorageConfig
 * - Routing intelligente cross-chain (BBTM, Algorand, Ethereum, Polygon)
 * - Analytics & storage pointer su IPFS (simulati on-chain — carica reale off-chain)
 *
 * NOTE: NON memorizzare segreti reali on-chain. I campi stringa sono placeholder.
 */

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/StringsUpgradeable.sol";

interface ILunaComicsFTReadable {
    function totalSupply() external view returns (uint256);
    function lunarGravity() external view returns (uint256);
}

interface IOceanMangaNFTReadable {
    // placeholder per futuri getter di sola lettura
}

contract UniversalMultiChainOrchestratorV2 is Initializable, AccessControlUpgradeable, UUPSUpgradeable {
    using StringsUpgradeable for uint256;

    // ─────────────────────────────────────────────────────────────────────────────
    // 🔐 ROLES & CONSTANTS
    // ─────────────────────────────────────────────────────────────────────────────
    bytes32 public constant CHAIN_MANAGER         = keccak256("CHAIN_MANAGER");
    bytes32 public constant ROUTE_OPTIMIZER       = keccak256("ROUTE_OPTIMIZER");
    bytes32 public constant CROSS_CHAIN_VALIDATOR = keccak256("CROSS_CHAIN_VALIDATOR");
    bytes32 public constant EMERGENCY_COORDINATOR = keccak256("EMERGENCY_COORDINATOR");
    bytes32 public constant GOVERNOR_ROLE         = keccak256("GOVERNOR_ROLE");     // config ecosistema
    bytes32 public constant MANAGER_ROLE          = keccak256("MANAGER_ROLE");      // registri operativi

    // Supported Chains
    uint256 public constant ETHEREUM_CHAIN = 1;
    uint256 public constant POLYGON_CHAIN  = 137;
    uint256 public constant ALGORAND_CHAIN = 999;
    uint256 public constant BBTM_CHAIN     = 888;

    // Soglie (indicative)
    uint256 public constant HIGH_URGENCY_THRESHOLD   = 100;   // ms
    uint256 public constant MEDIUM_URGENCY_THRESHOLD = 5000;  // ms
    uint256 public constant LOW_COST_THRESHOLD       = 1e15;  // 0.001 ETH eq.

    // ─────────────────────────────────────────────────────────────────────────────
    // 📊 MULTI-CHAIN ARCHITECTURE
    // ─────────────────────────────────────────────────────────────────────────────
    struct ChainConfiguration {
        uint256 chainId;
        string  chainName;
        address bridgeContract;
        address nativeToken;
        uint256 averageLatency;   // ms
        uint256 averageCost;      // wei eq.
        uint256 throughputTPS;
        uint256 energyEfficiency; // punteggio (più basso meglio)
        bool    isActive;
        bool    isHealthy;
        uint256 lastHealthCheck;
    }

    struct RouteOptimization {
        uint256 sourceChain;
        uint256 targetChain;
        string  transactionType;  // "payment","governance","reputation","emergency",...
        uint256 urgencyLevel;     // 1=LOW..4=CRITICAL
        uint256 amount;
        address user;
        uint256 recommendedChain;
        uint256 estimatedLatency;
        uint256 estimatedCost;
        string  reasoning;
    }

    struct CrossChainTransaction {
        bytes32 txId;
        address initiator;
        uint256 sourceChain;
        uint256 targetChain;
        address sourceContract;
        address targetContract;
        bytes   payload;
        uint256 timestamp;
        uint256 completedTimestamp;
        bool    isCompleted;
        bool    isFailed;
        string  status;
    }

    struct BridgePerformanceSnapshot {
        uint256 timestamp;
        uint256 chainId;
        uint256 successRate; // per mille o basis points, a scelta
        uint256 latency;
        uint256 cost;
        uint256 throughput;  // placeholder
        string  cid;         // IPFS CID con dettaglio esteso
    }

    // Quantum Links (NFT↔FT)
    struct QuantumLink {
        address user;
        uint256 tokenId;
        uint256 ftAmount;
        uint256 timestamp;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 💾 STATE VARIABLES
    // ─────────────────────────────────────────────────────────────────────────────
    mapping(uint256 => ChainConfiguration) public chainConfigs;
    mapping(bytes32  => CrossChainTransaction) public crossChainTxs;

    // preferenze e routing
    mapping(address => uint256) public userPreferredChains;
    mapping(string  => uint256) public transactionTypeOptimalChains;
    uint256[] public supportedChains;

    // bridge principali
    address public algorandBridge;
    address public ethereumPolygonBridge;
    address public bbtmInterface;

    // hub e moduli Solidary
    address public solidaryHub;
    address public reputationManager;

    // statistica
    uint256 public totalCrossChainTxs;
    uint256 public totalVolumeUSD;
    uint256 public totalGasSaved;
    uint256 public averageLatencyMs;

    // ecosistema Solidary (collegamenti)
    address public oceanMangaNFT;    // nftPlanetContract
    address public lunaComicsFT;     // ftSatelliteContract
    address public solidaryMetrics;  // facoltativo (solo tracking)

    // storage config (placeholder: non usare secrets reali)
    string public pinataJWT;
    string public nftStorageAPIKey;

    // analytics & IPFS pointers
    mapping(bytes32 => string) public transactionDataCIDs;    // txId -> CID
    mapping(uint256 => string[]) public chainAnalyticsCIDs;   // chain -> CIDs
    mapping(address => string[]) public userCrossChainHistoryCIDs; // utente -> CIDs

    // sostenibilità & performance
    uint256 public totalCarbonSaved;
    uint256 public totalEcoFriendlyTxs;
    uint256 public totalBBTMHighPerfTxs;
    BridgePerformanceSnapshot[] public bridgePerformanceHistory;

    // quantum links registry
    QuantumLink[] private _quantumLinks;
    uint256 private _totalStellarValueOverride; // opzionale: override manuale

    // ─────────────────────────────────────────────────────────────────────────────
    // 📣 EVENTS
    // ─────────────────────────────────────────────────────────────────────────────
    event ChainConfigured(uint256 indexed chainId, string chainName, address bridge);
    event RouteOptimized(bytes32 indexed txId, uint256 sourceChain, uint256 recommendedChain, string reasoning);
    event CrossChainTxInitiated(bytes32 indexed txId, address indexed user, uint256 sourceChain, uint256 targetChain);
    event CrossChainTxCompleted(bytes32 indexed txId, uint256 latency, uint256 cost);
    event ChainHealthUpdated(uint256 indexed chainId, bool healthy, uint256 latency, uint256 throughput);
    event EmergencyRoutingActivated(uint256 fromChain, uint256 toChain, string reason);

    event EcosystemLinked(address nftPlanet, address ftSatellite, address metrics);
    event StorageConfigured(bool setNftStorageKey, bool setPinataJwt);
    event CrossChainAnalyticsStored(bytes32 indexed txId, string analyticsCID);
    event CarbonFootprintCalculated(uint256 footprint, uint256 offset, string methodologyCID);
    event BridgePerformanceLogged(uint256 chainId, uint256 successRate, string performanceCID);
    event EcoRoutingSelected(bytes32 txId, uint256 carbonSaved, string reasoning);
    event QuantumLinkRecorded(uint256 indexed linkId, address indexed user, uint256 tokenId, uint256 ftAmount);

    // ─────────────────────────────────────────────────────────────────────────────
    // 🏗️ INITIALIZATION
    // ─────────────────────────────────────────────────────────────────────────────

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address admin,
        address _solidaryHub,
        address _reputationManager,
        address _algorandBridge,
        address _ethereumPolygonBridge,
        address _bbtmInterface,
        address _oceanMangaNFT,
        address _lunaComicsFT,
        address _solidaryMetrics
    ) public initializer {
        __AccessControl_init();
        __UUPSUpgradeable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(CHAIN_MANAGER, admin);
        _grantRole(ROUTE_OPTIMIZER, admin);
        _grantRole(CROSS_CHAIN_VALIDATOR, admin);
        _grantRole(EMERGENCY_COORDINATOR, admin);
        _grantRole(GOVERNOR_ROLE, admin);
        _grantRole(MANAGER_ROLE, admin);

        solidaryHub          = _solidaryHub;
        reputationManager    = _reputationManager;
        algorandBridge       = _algorandBridge;
        ethereumPolygonBridge= _ethereumPolygonBridge;
        bbtmInterface        = _bbtmInterface;

        oceanMangaNFT   = _oceanMangaNFT;
        lunaComicsFT    = _lunaComicsFT;
        solidaryMetrics = _solidaryMetrics;

        _initializeChainConfigurations();
        _setOptimalTransactionTypes();

        emit EcosystemLinked(oceanMangaNFT, lunaComicsFT, solidaryMetrics);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}

    // ─────────────────────────────────────────────────────────────────────────────
    // 🔧 CHAIN CONFIG
    // ─────────────────────────────────────────────────────────────────────────────

    function _initializeChainConfigurations() internal {
        chainConfigs[BBTM_CHAIN] = ChainConfiguration({
            chainId: BBTM_CHAIN,
            chainName: "BBTM Network",
            bridgeContract: bbtmInterface,
            nativeToken: address(0),
            averageLatency: 100,
            averageCost: 1e12,
            throughputTPS: 100000,
            energyEfficiency: 1,
            isActive: true,
            isHealthy: true,
            lastHealthCheck: block.timestamp
        });

        chainConfigs[ALGORAND_CHAIN] = ChainConfiguration({
            chainId: ALGORAND_CHAIN,
            chainName: "Algorand",
            bridgeContract: algorandBridge,
            nativeToken: address(0),
            averageLatency: 4500,
            averageCost: 1e15,
            throughputTPS: 6000,
            energyEfficiency: 2,
            isActive: true,
            isHealthy: true,
            lastHealthCheck: block.timestamp
        });

        chainConfigs[ETHEREUM_CHAIN] = ChainConfiguration({
            chainId: ETHEREUM_CHAIN,
            chainName: "Ethereum",
            bridgeContract: ethereumPolygonBridge,
            nativeToken: address(0),
            averageLatency: 15000,
            averageCost: 5e16,
            throughputTPS: 15,
            energyEfficiency: 8,
            isActive: true,
            isHealthy: true,
            lastHealthCheck: block.timestamp
        });

        chainConfigs[POLYGON_CHAIN] = ChainConfiguration({
            chainId: POLYGON_CHAIN,
            chainName: "Polygon",
            bridgeContract: ethereumPolygonBridge,
            nativeToken: address(0),
            averageLatency: 2000,
            averageCost: 1e16,
            throughputTPS: 7000,
            energyEfficiency: 4,
            isActive: true,
            isHealthy: true,
            lastHealthCheck: block.timestamp
        });

        supportedChains = [BBTM_CHAIN, ALGORAND_CHAIN, ETHEREUM_CHAIN, POLYGON_CHAIN];

        emit ChainConfigured(BBTM_CHAIN, "BBTM Network", bbtmInterface);
        emit ChainConfigured(ALGORAND_CHAIN, "Algorand",     algorandBridge);
        emit ChainConfigured(ETHEREUM_CHAIN, "Ethereum",     ethereumPolygonBridge);
        emit ChainConfigured(POLYGON_CHAIN,  "Polygon",      ethereumPolygonBridge);
    }

    function _setOptimalTransactionTypes() internal {
        transactionTypeOptimalChains["emergency"]      = BBTM_CHAIN;
        transactionTypeOptimalChains["high_frequency"] = BBTM_CHAIN;
        transactionTypeOptimalChains["eco_friendly"]   = ALGORAND_CHAIN;
        transactionTypeOptimalChains["governance"]     = POLYGON_CHAIN;
        transactionTypeOptimalChains["security"]       = ETHEREUM_CHAIN;
        transactionTypeOptimalChains["payment"]        = ALGORAND_CHAIN;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🧠 INTELLIGENT ROUTING
    // ─────────────────────────────────────────────────────────────────────────────

    function selectOptimalChain(
        string memory transactionType,
        uint256 amount,
        uint256 urgencyLevel,
        address user
    ) public view returns (ChainConfiguration memory) {
        // 1) Emergenza critica
        if (urgencyLevel == 4 || keccak256(bytes(transactionType)) == keccak256("emergency")) {
            return chainConfigs[BBTM_CHAIN];
        }
        // 2) Alta urgenza + importo basso
        if (urgencyLevel == 3 && amount < LOW_COST_THRESHOLD) {
            return chainConfigs[BBTM_CHAIN];
        }
        // 3) Eco-friendly / payment
        if (
            keccak256(bytes(transactionType)) == keccak256("eco_friendly") ||
            keccak256(bytes(transactionType)) == keccak256("payment")
        ) {
            return chainConfigs[ALGORAND_CHAIN];
        }
        // 4) Governance
        if (keccak256(bytes(transactionType)) == keccak256("governance")) {
            return chainConfigs[POLYGON_CHAIN];
        }
        // 5) High-value security
        if (amount > 1e18 && urgencyLevel <= 2) {
            return chainConfigs[ETHEREUM_CHAIN];
        }
        // 6) Preferenza utente
        if (userPreferredChains[user] != 0) {
            ChainConfiguration memory userChain = chainConfigs[userPreferredChains[user]];
            if (userChain.isActive && userChain.isHealthy) {
                return userChain;
            }
        }
        // 7) Default: Algorand
        return chainConfigs[ALGORAND_CHAIN];
    }

    function generateRouteOptimization(
        uint256 sourceChain,
        string memory transactionType,
        uint256 urgencyLevel,
        uint256 amount,
        address user
    ) public view returns (RouteOptimization memory) {
        ChainConfiguration memory optimal = selectOptimalChain(transactionType, amount, urgencyLevel, user);

        string memory reasoning;
        if (optimal.chainId == BBTM_CHAIN)      reasoning = "Selected BBTM for ultra-high performance";
        else if (optimal.chainId == ALGORAND_CHAIN) reasoning = "Selected Algorand for eco-efficiency";
        else if (optimal.chainId == POLYGON_CHAIN)  reasoning = "Selected Polygon for balanced performance";
        else                                         reasoning = "Selected Ethereum for maximum security";

        return RouteOptimization({
            sourceChain: sourceChain,
            targetChain: optimal.chainId,
            transactionType: transactionType,
            urgencyLevel: urgencyLevel,
            amount: amount,
            user: user,
            recommendedChain: optimal.chainId,
            estimatedLatency: optimal.averageLatency,
            estimatedCost: optimal.averageCost,
            reasoning: reasoning
        });
    }

    // Esegue la transazione cross-chain con logging analytics (CID simulato)
    function executeCrossChainTransaction(
        string memory transactionType,
        bytes memory payload,
        uint256 urgencyLevel,
        uint256 amount
    ) external returns (bytes32) {
        RouteOptimization memory route = generateRouteOptimization(
            block.chainid, transactionType, urgencyLevel, amount, msg.sender
        );

        bytes32 txId = keccak256(abi.encodePacked(
            msg.sender, transactionType, block.timestamp, totalCrossChainTxs
        ));

        CrossChainTransaction memory basicTx = CrossChainTransaction({
            txId: txId,
            initiator: msg.sender,
            sourceChain: block.chainid,
            targetChain: route.recommendedChain,
            sourceContract: address(this),
            targetContract: chainConfigs[route.recommendedChain].bridgeContract,
            payload: payload,
            timestamp: block.timestamp,
            completedTimestamp: 0,
            isCompleted: false,
            isFailed: false,
            status: "INITIATED"
        });

        crossChainTxs[txId] = basicTx;
        totalCrossChainTxs++;

        // Carbon footprint (semplificato)
        uint256 carbonFootprint = _calculateCarbonFootprint(route.recommendedChain, amount);

        if (route.recommendedChain == ALGORAND_CHAIN) {
            totalEcoFriendlyTxs++;
            totalCarbonSaved += carbonFootprint;
            emit EcoRoutingSelected(txId, carbonFootprint, "Algorand eco-friendly selection");
        }
        if (route.recommendedChain == BBTM_CHAIN) {
            totalBBTMHighPerfTxs++;
        }

        // Salva analytics su “IPFS” (simulato)
        string memory analyticsCID = _storeTransactionAnalytics(txId, basicTx, route, carbonFootprint);

        // update (eventi)
        emit RouteOptimized(txId, block.chainid, route.recommendedChain, route.reasoning);
        emit CrossChainTxInitiated(txId, msg.sender, block.chainid, route.recommendedChain);
        emit CrossChainAnalyticsStored(txId, analyticsCID);

        return txId;
    }

    function completeCrossChainTransaction(bytes32 txId)
        external
        onlyRole(CROSS_CHAIN_VALIDATOR)
    {
        CrossChainTransaction storage txData = crossChainTxs[txId];
        require(!txData.isCompleted, "Already completed");

        txData.isCompleted = true;
        txData.completedTimestamp = block.timestamp;
        txData.status = "COMPLETED";

        uint256 latency = block.timestamp - txData.timestamp;
        averageLatencyMs = (averageLatencyMs + latency) / 2;

        emit CrossChainTxCompleted(txId, latency, 0);
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 📊 MONITORING & HEALTH
    // ─────────────────────────────────────────────────────────────────────────────

    function updateChainHealth(
        uint256 chainId,
        bool isHealthy,
        uint256 latency,
        uint256 throughput
    ) external onlyRole(CHAIN_MANAGER) {
        ChainConfiguration storage config = chainConfigs[chainId];
        config.isHealthy = isHealthy;
        config.averageLatency = latency;
        config.throughputTPS = throughput;
        config.lastHealthCheck = block.timestamp;
        emit ChainHealthUpdated(chainId, isHealthy, latency, throughput);
    }

    function activateEmergencyRouting(
        uint256 fromChain,
        uint256 toChain,
        string memory reason
    ) external onlyRole(EMERGENCY_COORDINATOR) {
        chainConfigs[fromChain].isActive  = false;
        chainConfigs[fromChain].isHealthy = false;
        emit EmergencyRoutingActivated(fromChain, toChain, reason);
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 👁️ VIEW & ADMIN
    // ─────────────────────────────────────────────────────────────────────────────

    function getChainConfiguration(uint256 chainId) external view returns (ChainConfiguration memory) {
        return chainConfigs[chainId];
    }

    function getCrossChainTransaction(bytes32 txId) external view returns (CrossChainTransaction memory) {
        return crossChainTxs[txId];
    }

    function getSupportedChains() external view returns (uint256[] memory) {
        return supportedChains;
    }

    function getEcosystemStats() external view returns (uint256 totalTxs, uint256 volumeUSD, uint256 gasSaved, uint256 avgLatency) {
        return (totalCrossChainTxs, totalVolumeUSD, totalGasSaved, averageLatencyMs);
    }

    function calculateCarbonFootprint() external view returns (uint256) {
        uint256 totalFootprint = 0;
        for (uint256 i = 0; i < supportedChains.length; i++) {
            ChainConfiguration memory config = chainConfigs[supportedChains[i]];
            totalFootprint += config.energyEfficiency;
        }
        return totalFootprint;
    }

    function setUserPreferredChain(address user, uint256 chainId) external onlyRole(CHAIN_MANAGER) {
        userPreferredChains[user] = chainId;
    }

    function updateBridgeContracts(
        address _algorandBridge,
        address _ethereumPolygonBridge,
        address _bbtmInterface
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_algorandBridge       != address(0)) algorandBridge        = _algorandBridge;
        if (_ethereumPolygonBridge!= address(0)) ethereumPolygonBridge = _ethereumPolygonBridge;
        if (_bbtmInterface        != address(0)) bbtmInterface         = _bbtmInterface;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🌐 STORAGE (placeholders) & ECOSYSTEM WIRING
    // ─────────────────────────────────────────────────────────────────────────────

    function configureStorage(string memory _nftStorageKey, string memory _pinataJWT)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        nftStorageAPIKey = _nftStorageKey;
        pinataJWT        = _pinataJWT;
        emit StorageConfigured(bytes(_nftStorageKey).length > 0, bytes(_pinataJWT).length > 0);
    }

    function setSolidaryEcosystem(
        address _nftPlanet,
        address _ftSatellite,
        address _metrics
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        oceanMangaNFT   = _nftPlanet;
        lunaComicsFT    = _ftSatellite;
        solidaryMetrics = _metrics;
        emit EcosystemLinked(oceanMangaNFT, lunaComicsFT, solidaryMetrics);
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🔗 SOLIDARY METRICS – REQUIRED API
    // ─────────────────────────────────────────────────────────────────────────────

    function nftPlanetContract() external view returns (address) {
        return oceanMangaNFT;
    }

    function ftSatelliteContract() external view returns (address) {
        return lunaComicsFT;
    }

    function totalQuantumLinks() external view returns (uint256) {
        return _quantumLinks.length;
    }

    function totalStellarValue() external view returns (uint256) {
        if (_totalStellarValueOverride > 0) return _totalStellarValueOverride;
        address ft = lunaComicsFT;
        if (ft == address(0)) return 0;
        uint256 supply  = ILunaComicsFTReadable(ft).totalSupply();
        uint256 gravity = ILunaComicsFTReadable(ft).lunarGravity();
        if (gravity == 0) return 0;
        return (supply * gravity) / 1e18;
    }

    function getStorageConfig() external view returns (string memory, string memory) {
        return (nftStorageAPIKey, pinataJWT);
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🔭 QUANTUM LINK REGISTRY
    // ─────────────────────────────────────────────────────────────────────────────

    function recordQuantumLink(address user, uint256 tokenId, uint256 ftAmount)
        external
        onlyRole(MANAGER_ROLE)
        returns (uint256 linkId)
    {
        _quantumLinks.push(QuantumLink({
            user: user,
            tokenId: tokenId,
            ftAmount: ftAmount,
            timestamp: block.timestamp
        }));
        linkId = _quantumLinks.length - 1;
        emit QuantumLinkRecorded(linkId, user, tokenId, ftAmount);
    }

    function getQuantumLink(uint256 index) external view returns (address user, uint256 tokenId, uint256 ftAmount, uint256 timestamp) {
        require(index < _quantumLinks.length, "Index out of range");
        QuantumLink memory ql = _quantumLinks[index];
        return (ql.user, ql.tokenId, ql.ftAmount, ql.timestamp);
    }

    function quantumLinksCount() external view returns (uint256) {
        return _quantumLinks.length;
    }

    function setTotalStellarValueOverride(uint256 valueOrZero) external onlyRole(GOVERNOR_ROLE) {
        _totalStellarValueOverride = valueOrZero;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 📊 ANALYTICS & IPFS (simulazione on-chain)
    // ─────────────────────────────────────────────────────────────────────────────

    function _storeTransactionAnalytics(
        bytes32 txId,
        CrossChainTransaction memory txData,
        RouteOptimization memory route,
        uint256 carbonFootprint
    ) internal returns (string memory) {
        bytes memory analyticsData = abi.encodePacked(
            '{"txId":"', _bytes32ToHexString(txId),
            '","initiator":"', _addressToString(txData.initiator),
            '","sourceChain":', _u(txData.sourceChain),
            ',"targetChain":', _u(txData.targetChain),
            ',"transactionType":"', route.transactionType,
            '","urgencyLevel":', _u(route.urgencyLevel),
            ',"amount":', _u(route.amount),
            ',"estimatedLatency":', _u(route.estimatedLatency),
            ',"estimatedCost":', _u(route.estimatedCost),
            ',"carbonFootprint":', _u(carbonFootprint),
            ',"timestamp":', _u(block.timestamp),
            ',"routingReasoning":"', route.reasoning,
            '","chainName":"', chainConfigs[route.recommendedChain].chainName,
            '"}'
        );

        string memory cid = _uploadToIPFS(analyticsData);
        transactionDataCIDs[txId] = cid;
        chainAnalyticsCIDs[txData.targetChain].push(cid);
        userCrossChainHistoryCIDs[txData.initiator].push(cid);
        return cid;
    }

    function logBridgePerformance(
        uint256 chainId,
        uint256 successRate,
        uint256 latency,
        uint256 cost
    ) external onlyRole(CHAIN_MANAGER) {
        bytes memory performanceData = abi.encodePacked(
            '{"chainId":', _u(chainId),
            ',"successRate":', _u(successRate),
            ',"latency":', _u(latency),
            ',"cost":', _u(cost),
            ',"timestamp":', _u(block.timestamp),
            ',"totalTxs":', _u(totalCrossChainTxs),
            '}'
        );

        string memory cid = _uploadToIPFS(performanceData);
        bridgePerformanceHistory.push(BridgePerformanceSnapshot({
            timestamp: block.timestamp,
            chainId: chainId,
            successRate: successRate,
            latency: latency,
            cost: cost,
            throughput: 0,
            cid: cid
        }));

        emit BridgePerformanceLogged(chainId, successRate, cid);
    }

    function getUserCrossChainHistory(address user) external view returns (string[] memory cids) {
        return userCrossChainHistoryCIDs[user];
    }

    function getChainPerformanceHistory(uint256 chainId, uint256 limit) external view returns (BridgePerformanceSnapshot[] memory) {
        // filtra fino a "limit" elementi per chainId
        uint256 count;
        for (uint256 i = 0; i < bridgePerformanceHistory.length; i++) {
            if (bridgePerformanceHistory[i].chainId == chainId) count++;
        }
        uint256 resultCount = (limit == 0 || limit > count) ? count : limit;
        BridgePerformanceSnapshot[] memory result = new BridgePerformanceSnapshot[](resultCount);
        uint256 idx;
        for (uint256 i = 0; i < bridgePerformanceHistory.length && idx < resultCount; i++) {
            if (bridgePerformanceHistory[i].chainId == chainId) {
                result[idx] = bridgePerformanceHistory[i];
                idx++;
            }
        }
        return result;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🌱 CARBON FOOTPRINT (semplificato)
    // ─────────────────────────────────────────────────────────────────────────────

    function _calculateCarbonFootprint(uint256 chainId, uint256 amount) internal view returns (uint256) {
        ChainConfiguration memory config = chainConfigs[chainId];
        uint256 baseFootprint   = config.energyEfficiency;
        uint256 amountMultiplier= (amount > 1e18) ? 2 : 1;
        uint256 footprint       = baseFootprint * amountMultiplier;
        if (chainId == ALGORAND_CHAIN) footprint = footprint / 2;
        if (chainId == BBTM_CHAIN)     footprint = footprint / 4;
        return footprint;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🧰 IPFS SIM (on-chain)
    // ─────────────────────────────────────────────────────────────────────────────

    function _uploadToIPFS(bytes memory data) internal view returns (string memory cid) {
        bytes32 hash = keccak256(abi.encodePacked(data, block.timestamp, totalCrossChainTxs));
        // pseudo-CID esadecimale
        cid = string(abi.encodePacked("simulated:ipfs:", _bytes32ToHexString(hash)));
        return cid;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // 🔎 UTILS
    // ─────────────────────────────────────────────────────────────────────────────

    function _bytes32ToHexString(bytes32 v) internal pure returns (string memory) {
        bytes memory s = new bytes(64);
        for (uint256 i = 0; i < 32; i++) {
            bytes1 b = v[i];
            bytes1 hi = bytes1(uint8(b) / 16);
            bytes1 lo = bytes1(uint8(b) % 16);
            s[2*i]   = _nibble(hi);
            s[2*i+1] = _nibble(lo);
        }
        return string(s);
    }

    function _nibble(bytes1 b) internal pure returns (bytes1 c) {
        uint8 v = uint8(b);
        if (v < 10) return bytes1(v + 0x30);
        return bytes1(v + 0x57);
    }

    function _addressToString(address a) internal pure returns (string memory) {
        return StringsUpgradeable.toHexString(uint256(uint160(a)), 20);
    }

    function _u(uint256 x) internal pure returns (string memory) {
        return x.toString();
    }
}

